/** Synthetic format fixtures; shares the PNGs generated by epub-startup-fixtures.py. */
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const {execFileSync}=require('node:child_process');
const {mobiFixture}=require('../helpers/mobiFixture.cjs');
const root=path.resolve(process.argv[2]||'.cache/experience1186/fixtures');
fs.mkdirSync(root,{recursive:true});
execFileSync('python',['tests/android/epub-startup-fixtures.py',root],{stdio:'inherit',windowsHide:true});
const image=fs.readFileSync(path.join(root,'Startup.png'));
fs.writeFileSync(path.join(root,'StartupText.mobi'),mobiFixture(Array.from({length:16},(_,i)=>`<h1>Chapter ${i+1}</h1><p>Omi reader text ${i+1}. ${'Reader verification content. '.repeat(120)}</p>`)));
fs.writeFileSync(path.join(root,'StartupPictures.mobi'),mobiFixture(Array.from({length:8},()=>'<img recindex="1"/>'),[image]));
for(const [input,output] of [['tests/fixtures/android-archives/RAR5.cbr','Startup.cbr'],['tests/fixtures/android-archives/Solid.cb7','Startup.cb7'],['tests/fixtures/documents/three-pages.pdf','Startup.pdf']])fs.copyFileSync(input,path.join(root,output));
const files=fs.readdirSync(root,{withFileTypes:true}).filter(item=>item.isFile()&&item.name.startsWith('Startup')&&!item.name.endsWith('.json')).map(item=>{const bytes=fs.readFileSync(path.join(root,item.name));return{name:item.name,bytes:bytes.length,sha256:crypto.createHash('sha256').update(bytes).digest('hex')};});
fs.writeFileSync(path.join(root,'startup-formats-sha256.json'),JSON.stringify(files,null,2)+'\n');
console.log(JSON.stringify(files));
